	["Partes de Alfa apagadas"] = "Alfa parts turned off",
	["Están apagadas en tu lista de addons: %s. Sin ellas faltan páginas de Alfa."] = "They're turned off in your addon list: %s. Without them, Alfa is missing pages.",
	["Activar módulo"] = "Turn on module",
