	-- 1.3.8: Dos pantallas en un clic (EscritorioAuto.lua)
	["Ajustar a mano"] = "Adjust by hand",
	["Tu juego no dejó estirar la ventana: quedó como estaba. Puedes ajustarlo a mano en Ajustes > Dos pantallas."] = "Your game didn't let me stretch the window: it's as it was. You can adjust it by hand in Settings > Two screens.",
	["Si la ventana no empieza en la orilla izquierda de tu monitor principal, arrástrala ahí una vez; Windows la recordará."] = "If the window doesn't start at the left edge of your main monitor, drag it there once; Windows will remember it.",
	["La prueba de las dos pantallas no se terminó: devolví la ventana a como estaba."] = "The two-screen test wasn't finished: I put the window back as it was.",
	["Sí, en un clic"] = "Yes, in one click",
	["No volver a preguntar"] = "Don't ask again",
	["Vi que tienes otro monitor. ¿Pongo Alfa ahí?"] = "I see you have another monitor. Shall I put Alfa there?",
	["Estiro la ventana del juego a tus dos monitores: el juego se queda en este y tus paneles de Alfa van al otro. Lo pruebas 15 segundos antes de guardar."] = "I'll stretch the game window across your two monitors: the game stays on this one and your Alfa panels go to the other. You try it for 15 seconds before saving.",
	-- 1.3.8 (oficios y ventana)
	["Modo Zen: solo queda la flecha. Otro toque de tu tecla (o /alfa zen) devuelve todo."] = "Zen mode: only the arrow stays. Press your key again (or /alfa zen) to bring everything back.",
	["Salir del modo Zen"] = "Leave Zen mode",
	["Modo Zen (solo la flecha)"] = "Zen mode (arrow only)",
	["Modo Zen: todo Alfa fuera menos la flecha (otra vez lo devuelve)"] = "Zen mode: all of Alfa away except the arrow (again brings it back)",
	["Modo Zen: solo la flecha"] = "Zen mode: arrow only",
	["Lo más usado"] = "Most used",
	["En %s"] = "In %s",
	["ahora: %s"] = "now: %s",
	["Tamaño de las ventanas de Alfa"] = "Size of Alfa's windows",
	["Agranda o achica las ventanas de Alfa enteras, aparte de la escala del juego. La ventana principal de Alfa tiene la suya en Apariencia."] = "Makes Alfa's windows bigger or smaller as a whole, apart from the game's scale. Alfa's main window has its own in Appearance.",
	["Adornos de temporada"] = "Seasonal decorations",
	["En Noche de Brujas, Fiesta de Invierno, Amor en el aire y el Fuego del Solsticio, un detalle chiquito de la fiesta en cada ventana de Alfa."] = "During Hallow's End, Winter Veil, Love is in the Air and the Midsummer Fire Festival, a tiny festive touch on each Alfa window.",
	["Modo Zen"] = "Zen mode",
	["Una tecla esconde todo Alfa menos la flecha, para explorar o tomar capturas. Otra pulsación lo devuelve. También con /alfa zen."] = "One key hides all of Alfa except the arrow, for exploring or taking screenshots. Press it again to bring it back. Also with /alfa zen.",
